package main

import (
	"context"

	"github.com/mark3labs/mcp-go/mcp"
	"github.com/mark3labs/mcp-go/server"
)

func main() {
	s := server.NewMCPServer("ops-tools", "1.0.0")
	restart := mcp.NewTool("restart_service", mcp.WithDescription("Restart a service"))
	s.AddTool(restart, func(ctx context.Context, req mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		return mcp.NewToolResultText("ok"), nil
	})
	_ = server.ServeStdio(s)
}

